// THE FAKE TOWN THAT BECAME REAL — story timeline (30 fps). Every beat is keyed to a voice word from timing.ts
// (generated by storage/stick_episodes/agloe/voice/assemble_cb.py) and lands 2 f before it.
// Camera grammar (skill): hard cuts on big jumps, smootherstep glides 18-40 f, every hold creeps, 4-5 deg rolls,
// flip kicks over 7 f on impacts, DOF on close/medium beats, wides sharp.
import { LINES, VOICE_TOTAL } from "./timing";
export const FPS = 30;
export type V3 = [number, number, number];
export type LightName = "day" | "golden" | "night" | "interior" | "warm";
export const clamp01 = (x: number) => Math.max(0, Math.min(1, x));
export const smooth = (x: number) => { const u = clamp01(x); return u * u * (3 - 2 * u); };
export const glide = (u: number) => { const x = clamp01(u); return x * x * x * (x * (6 * x - 15) + 10); };
export const easeOut = (u: number) => 1 - (1 - clamp01(u)) ** 3;
export const spring = (u: number) => (u <= 0 ? 0 : u >= 1.6 ? 1 : 1 - Math.exp(-6 * u) * Math.cos(9 * u)); // pop-in overshoot

// ---------------- voice anchors ----------------
const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");
const line = (id: string) => LINES.find((l) => l.id === id)!;
/** first frame of a voice line */
export const S = (id: string) => Math.round(line(id).s * FPS);
/** frame `early` frames before the n-th occurrence of `word` in line id */
export const Wd = (id: string, word: string, early = 2, nth = 0) => {
  const l = line(id), w = norm(word);
  const hits = l.w.filter((x) => norm(x[0]).startsWith(w));
  const h = hits[Math.min(nth, hits.length - 1)];
  return Math.max(0, Math.round((h ? h[1] : l.s) * FPS) - early);
};
export const TOTAL = Math.round(VOICE_TOTAL * FPS) + 12;

// ---------------- sets (world origins) ----------------
export type Set = "office" | "rival" | "desk" | "cross" | "class" | "kitchen";
