const KICKS: [number, number][] = [[EV.real + 2, 0.05], [EV.ours, 0.05], [EV.scram, 0.025], [EV.copied, 0.04], [EV.gotcha + 1, 0.07], [EV.check, 0.06], [EV.stampA, 0.06], [EV.dollar, 0.02]];
export const kickAt = (f: number) => {
  let a = 0;
  for (const [fk, amp] of KICKS) { const d = f - fk; if (d >= 0 && d < 7) a += amp * (1 - d / 7) ** 1.5 * (d % 2 ? -1 : 1); }
  return a;
};
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const lerp3 = (a: V3, b: V3, t: number): V3 => [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
export const camAt = (id: number, f: number): Cam => {
  const keys = CAMS[id];
  let cur = keys[0], pos = cur.pos, look = cur.look, fov = cur.fov ?? 40, roll = cur.roll ?? 0, settled = keys[0].f;
  for (let i = 1; i < keys.length; i++) {
    const kk = keys[i];
    if (f < kk.f) break;
    const u = glide((f - kk.f) / (kk.dur ?? 24));
    pos = lerp3(pos, kk.pos, u); look = lerp3(look, kk.look, u); fov = lerp(fov, kk.fov ?? fov, u); roll = lerp(roll, kk.roll ?? roll, u);
    cur = kk; settled = kk.f + (kk.dur ?? 24);
  }
  // every hold creeps toward its look point (never a static hold >= 4 f)
  const creep = Math.min(0.4, Math.max(0, f - Math.min(settled, f)) * (cur.creep ?? 0.002) + Math.max(0, f - keys[0].f) * 0.0005);
  pos = lerp3(pos, look, creep);
  const kick = kickAt(f);
  return { pos: [pos[0], pos[1] + kick, pos[2]], look, fov, roll: roll + kick * 0.5, aim: cur.aim };
};

// ---------------- depth of field (cInf px at 1080 wide) ----------------
export type Dof = { cInf: number; focus?: V3 };
const DOFS: Record<number, (f: number) => Dof> = {
  1: () => ({ cInf: 10, focus: O("desk", M) }),
  2: (f) => ({ cInf: f < EV.real - 10 ? 0 : 5, focus: O("cross", LODGE) }),
  3: () => ({ cInf: 7 }),
  4: () => ({ cInf: 13, focus: O("desk", [-0.12, MAP_Y, 0.0]) }),
  5: () => ({ cInf: 9 }),
  6: () => ({ cInf: 13 }),
  7: () => ({ cInf: 8 }),
  8: () => ({ cInf: 0 }),
  9: () => ({ cInf: 12, focus: O("desk", M) }),
  10: () => ({ cInf: 12, focus: O("desk", M) }),
  11: (f) => ({ cInf: f < EV.friend ? 7 : 11, focus: f < EV.friend ? undefined : O("class", [0.25, 0.85, -0.4]) }),
  12: (f) => ({ cInf: f < EV.there ? 6 : 12, focus: O("desk", M) }),
  13: () => ({ cInf: 12 }),
  14: () => ({ cInf: 5 }),
  15: () => ({ cInf: 11 }),
  16: (f) => ({ cInf: f < EV.renamed ? 0 : 6, focus: O("cross", [-8.5, 2.6, -4.8]) }),
  17: () => ({ cInf: 9 }),
  18: (f) => ({ cInf: f < EV.dollar ? 7 : 12, focus: f < EV.buyer ? O("kitchen", [0.05, 0.86, -0.25]) : undefined }),
  19: () => ({ cInf: 11 }),
  20: (f) => ({ cInf: f < EV.gov - 8 ? 9 : 0 }),
};
export const dofAt = (f: number) => DOFS[shotAt(f).id](f);
export const dofFor = (id: number, f: number) => DOFS[id](f);
